START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101013823_AddDailyNotifications') THEN
    CREATE TABLE "NotificationDevices" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "EndpointHash" character varying(64) NOT NULL,
        "AuthorizationStampHash" text NOT NULL,
        "ProtectedSubscription" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "LastTestAt" timestamp with time zone,
        CONSTRAINT "PK_NotificationDevices" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_NotificationDevices_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101013823_AddDailyNotifications') THEN
    CREATE TABLE "NotificationPreferences" (
        "UserId" integer NOT NULL,
        "MorningEnabled" boolean NOT NULL,
        "MorningTime" time without time zone NOT NULL,
        "EveningEnabled" boolean NOT NULL,
        "EveningTime" time without time zone NOT NULL,
        "Language" character varying(2) NOT NULL,
        CONSTRAINT "PK_NotificationPreferences" PRIMARY KEY ("UserId"),
        CONSTRAINT "FK_NotificationPreferences_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101013823_AddDailyNotifications') THEN
    CREATE TABLE "NotificationDeliveries" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "DeviceId" integer NOT NULL,
        "Key" character varying(100) NOT NULL,
        "Kind" character varying(20) NOT NULL,
        "Date" date NOT NULL,
        "Count" integer NOT NULL,
        "ExpiresAt" timestamp with time zone NOT NULL,
        "NextAttemptAt" timestamp with time zone NOT NULL,
        "LockedUntil" timestamp with time zone,
        "Attempts" integer NOT NULL,
        "Finished" boolean NOT NULL,
        CONSTRAINT "PK_NotificationDeliveries" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_NotificationDeliveries_NotificationDevices_DeviceId" FOREIGN KEY ("DeviceId") REFERENCES "NotificationDevices" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101013823_AddDailyNotifications') THEN
    CREATE UNIQUE INDEX "IX_NotificationDeliveries_DeviceId_Key" ON "NotificationDeliveries" ("DeviceId", "Key");
    END IF;
END $EF$;

